import {dayNumber} from './age.js';
export const IMPORT_FIELDS={occupation:'Tytuł ubezpieczenia',coverage:'Ubezpieczenie chorobowe',insuranceFrom:'Początek chorobowego',insuranceTo:'Koniec chorobowego',birthDate:'Data urodzenia rodzica',basis:'Podstawa zasiłku potwierdzona przez płatnika',salary:'Stałe wynagrodzenie brutto',debt:'Zadłużenie na dzień prawa','sickness.start':'Początek niezdolności','sickness.days':'Dni niezdolności','sickness.certificate':'Zaświadczenie medyczne','sickness.pregnant':'Kod B / potwierdzona ciąża',eventDate:'Poród / przyjęcie',childBirthDate:'Data urodzenia dziecka',adoptionCourtDate:'Prawomocność adopcji',count:'Liczba dzieci'};
const importFold=s=>String(s).normalize('NFD').replace(/\p{M}/gu,'').replace(/ł/g,'l').toLowerCase().replace(/[^a-z0-9]/g,'');
export function importDate(value){const v=String(value||'').trim(),date=/^\d{4}-\d{2}-\d{2}$/.test(v)?v:/^\d{2}[.\/-]\d{2}[.\/-]\d{4}$/.test(v)?v.slice(6)+'-'+v.slice(3,5)+'-'+v.slice(0,2):'';if(!date)return null;try{dayNumber(date);return date;}catch{return null;}}
export function occupationFromZusCode(code){const v=String(code).replace(/\s/g,'');if(!/^\d{6}$/.test(v))return null;return ({'0110':'employee','0111':'employee','0411':'contract','0417':'contract','0510':'business','0512':'business','0570':'business','0572':'business','0590':'business','0592':'business','0540':'startup'})[v.slice(0,4)]||null;}
function importSuggestion(field,value,evidence,record=0){return {field,value,evidence:String(evidence||'').slice(0,350),record,selected:false};}
export function parseZusXml(text){
 if(text.length>2000000||/<!DOCTYPE|<!ENTITY/i.test(text))throw new Error('XML jest za duży lub zawiera niedozwolone deklaracje.');
 const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw new Error('Nieprawidłowy XML.');
 const all=(node,name)=>[...node.getElementsByTagNameNS('*',name)],get=(node,name)=>all(node,name)[0]?.textContent.trim()||'',root=xml.documentElement.localName;
 const out={kind:'XML użytkownika',demo:xml.documentElement.getAttribute('data-demo')==='true',suggestions:[],observed:[],warnings:['Odczyt nie potwierdza autentyczności dokumentu ani pieczęci elektronicznej.'],text:''};
 if(root==='potwierdzenie'){
  out.kind='Potwierdzenie danych ZUS (XML)';out.documentDate=importDate(get(xml,'data_potwierdzenia')||get(xml,'data_pisma'));if(out.documentDate)out.observed.push('Dane potwierdzono na: '+out.documentDate);
  const person=all(xml,'blok_danych_ubezpieczonego')[0]||all(xml,'blok_danych_swiadczeniobiorcy')[0];if(person)out.person=[get(person,'imie'),get(person,'nazwisko')].filter(Boolean).join(' ');
  let record=0;for(const section of all(xml,'zgloszenia_do_ubezpieczen_chorobowe'))for(const item of all(section,'zgloszenie_do_ubezpieczen')){
   const code=get(item,'kod_tytulu_ubezpieczenia'),occupation=occupationFromZusCode(code),from=importDate(get(item,'data_od')),to=importDate(get(item,'data_do'));
   if(occupation){out.suggestions.push(importSuggestion('occupation',occupation,'Chorobowe, kod tytułu '+code,record));if(['employee','contract','business'].includes(occupation))out.suggestions.push(importSuggestion('coverage',occupation==='employee'?'compulsory':'voluntary','Wykazano zgłoszenie do chorobowego; potwierdź zbiegi tytułów.',record));}
   else out.observed.push('Nierozpoznany kod tytułu '+code+' — wymaga ręcznego przypisania.');
   if(from)out.suggestions.push(importSuggestion('insuranceFrom',from,'Zgłoszenie do chorobowego — data_od',record));if(to)out.suggestions.push(importSuggestion('insuranceTo',to,'Zgłoszenie do chorobowego — data_do (bez przyczyny ustania)',record));record++;
  }
  for(const tag of ['podstawy_wymiaru_skladek_emerytalne_rentowe','podstawy_wymiaru_skladek_zdrowotne'])if(all(xml,tag).length)out.observed.push('Dokument zawiera podstawy składek emerytalnych/rentowych lub zdrowotnych. Nie zostały uznane za podstawę zasiłku.');
  for(const item of all(xml,'swiadczenie').filter(item=>item.parentElement?.localName==='lista_swiadczen'))out.observed.push('Historia świadczeń: '+[get(item,'rodzaj_swiadczenia'),get(item,'okres_od'),get(item,'okres_do'),get(item,'kwota_brutto')?'brutto '+get(item,'kwota_brutto'):'',get(item,'kwota_netto')?'netto '+get(item,'kwota_netto'):''].filter(Boolean).join(' · '));
  if(!out.suggestions.length)out.warnings.push('Brak rozpoznanego zakresu chorobowego nie dowodzi braku ubezpieczenia. Uzupełnij dane lub wygeneruj potwierdzenie z właściwym zakresem.');
  out.warnings.push('Podstawa składek, wynagrodzenie i podstawa zasiłku są różnymi wartościami. Saldo nie potwierdza długu na przyszły dzień prawa. Zgłoszenie rodziny do zdrowotnego nie potwierdza adopcji.');
 }else if(root==='raportEzla'){
  out.kind='Raport e-ZLA (XML)';let index=0;
  for(const item of all(xml,'daneDokumentu')){const status=get(item,'status');if(/anul|koryg/i.test(status)){out.observed.push('Pominięto dokument o statusie: '+status);continue;}const from=importDate(get(item,'dataOd')),to=importDate(get(item,'dataDo'));if(from&&to&&to>=from){out.suggestions.push(importSuggestion('sickness.start',from,'Okres zwolnienia — potwierdź wybrany dokument',index),importSuggestion('sickness.days',dayNumber(to)-dayNumber(from)+1,'Koniec zwolnienia '+to,index),importSuggestion('sickness.certificate','yes','Dokument e-ZLA',index));if(/^(true|1|tak|B)$/i.test(get(item,'kodChorobyB')))out.suggestions.push(importSuggestion('sickness.pregnant',true,'Kod B w dokumencie',index));}index++;}
 }else throw new Error('Ten XML nie ma rozpoznanej struktury potwierdzenia ZUS ani raportu e-ZLA. Wybierz PDF lub przepisz właściwe pola ręcznie.');
 return out;
}
const importAliases={tytulubezpieczenia:'occupation',ubezpieczeniechorobowe:'coverage',poczatekubezpieczeniachorobowego:'insuranceFrom',koniecubezpieczeniachorobowego:'insuranceTo',dataurodzeniarodzica:'birthDate',podstawawymiaruzasilku:'basis',podstawazasilku:'basis',stalewynagrodzeniebrutto:'salary',zadluzenienadzienprawa:'debt',poczatekzwolnienia:'sickness.start',liczbadnizwolnienia:'sickness.days',dataporodu:'eventDate',dataurodzeniadziecka:'childBirthDate',dataprawomocnosciadopcji:'adoptionCourtDate',liczbadzieci:'count'};
export function suggestionsFromText(text,kind='Dokument użytkownika'){
 const suggestions=[],observed=[];for(const line of text.split(/\r?\n/)){const match=line.match(/^\s*([^:;=]{2,100})\s*[:;=]\s*(.{1,160})$/);if(!match)continue;const field=importAliases[importFold(match[1])];if(!field)continue;let value=match[2].trim().replace(/^"|"$/g,'');if(!value)continue;if(/Date$|From$|To$|birthDate|eventDate|\.start/.test(field)){value=importDate(value);if(!value)continue;}else if(['basis','salary','debt','count','sickness.days'].includes(field)){value=Number(value.replace(/\s|zł|PLN/g,'').replace(',','.'));if(!Number.isFinite(value)||value<0)continue;}else{const f=importFold(value);value=field==='occupation'?({umowaoprace:'employee',pracownik:'employee',dzialalnoscgospodarcza:'business',jdg:'business',zlecenie:'contract',brak:'uninsured'})[f]||value:({obowiazkowe:'compulsory',dobrowolne:'voluntary',brak:'none',nieznane:'unknown'})[f]||value;}suggestions.push(importSuggestion(field,value,line));}
 if(!suggestions.length)observed.push('Nie znaleziono jednoznacznie oznaczonych pól do automatycznego przypisania. Treść dokumentu możesz odczytać i wskazać wartości ręcznie.');
 return {kind,suggestions,observed,warnings:['Wartości są propozycjami odczytu. Sprawdź właściciela danych, rodzaj podstawy i właściwy okres; dopiero zaznaczone pola zostaną zastosowane.'],text:text.slice(0,80000)};
}
export async function readImportFile(file){
 if(file.size>15000000)throw new Error('Plik może mieć najwyżej 15 MB.');
 if(/\.xml$/i.test(file.name))return parseZusXml(await file.text());
 if(/\.pdf$/i.test(file.name)){
  const {getDocument,GlobalWorkerOptions}=await import('./vendor/pdf.mjs');GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
  const task=getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useWasm:false,useWorkerFetch:false,stopAtErrors:false});let pdf;
  try{pdf=await task.promise;if(pdf.numPages>100)throw new Error('Wybierz dokument do 100 stron.');const parts=[];const fields=await pdf.getFieldObjects();if(fields)for(const [key,items]of (fields instanceof Map?[...fields]:Object.entries(fields)))for(const item of items)if(item.value!==undefined&&item.value!==null)parts.push(key+': '+String(item.value));for(let page=1;page<=pdf.numPages;page++){const p=await pdf.getPage(page),content=await p.getTextContent();let line='';for(const item of content.items){line+=item.str+' ';if(item.hasEOL){parts.push(line);line='';}}if(line)parts.push(line);}const result=suggestionsFromText(parts.join('\n'),'PDF użytkownika — '+pdf.numPages+(pdf.numPages===1?' strona':pdf.numPages<5?' strony':' stron'));result.demo=/SYNTETYCZNY PRZYKLAD TESTOWY/.test(result.text);if(!result.text.trim())result.warnings.push('PDF może być skanem. Odczyt obrazu (OCR) nie jest dostępny; dodaj wartości ręcznie.');return result;}finally{await task.destroy();}
 }
 if(/\.(csv|txt)$/i.test(file.name))return suggestionsFromText(await file.text(),'Tekst / CSV użytkownika');
 throw new Error('Wybierz PDF, XML, CSV lub TXT.');
}
export function applyImportedFields(input,fields,parent=0,title=0){
 const next=structuredClone(input);if(![0,1].includes(parent)||!Number.isInteger(title)||title<0||title>3)throw new Error('Wybierz rodzica i tytuł.');
 for(const item of fields){if(!Object.hasOwn(IMPORT_FIELDS,item.field))throw new Error('Nieobsługiwane pole importu.');const f=item.field;if(/Date$|From$|To$|birthDate|eventDate|\.start/.test(f)){if(!importDate(item.value))throw new Error('Nieprawidłowa data importowanego pola.');}else if(['basis','salary','debt','count','sickness.days'].includes(f)){const value=Number(String(item.value).replace(',','.'));if(!Number.isFinite(value)||value<0||value>1e8)throw new Error('Nieprawidłowa wartość liczbowa importu.');}else if(f==='occupation'&&!['employee','contract','business','uninsured','startup','krus','student','work','unregistered'].includes(item.value))throw new Error('Wybierz prawidłowy tytuł ubezpieczenia.');else if(f==='coverage'&&!['compulsory','voluntary','none','unknown'].includes(item.value))throw new Error('Wybierz prawidłowy rodzaj chorobowego.');}
 const base=next.parents[parent];let target=base;if(title){base.extraTitles??=[];while(base.extraTitles.length<title)base.extraTitles.push({occupation:'employee',coverage:'unknown',basisMode:'known',basis:null,history:[],fte:1});target=base.extraTitles[title-1];}
 for(let item of fields){if(!Object.hasOwn(IMPORT_FIELDS,item.field))throw new Error('Nieobsługiwane pole importu.');const f=item.field;if(/Date$|From$|To$|birthDate|eventDate|\.start/.test(f))item={...item,value:importDate(item.value)};else if(['basis','salary','debt','count','sickness.days'].includes(f))item={...item,value:Number(String(item.value).replace(',','.'))};else if(f==='sickness.pregnant')item={...item,value:item.value===true||/^(true|1|tak|B)$/i.test(String(item.value))};if(item.field.startsWith('sickness.'))next.sickness[item.field.slice(9)]=item.value;else if(['eventDate','childBirthDate','adoptionCourtDate','count'].includes(item.field))next[item.field]=item.value;else target[item.field]=item.value;}
 if(fields.some(f=>f.field==='basis'))target.basisMode='known';else if(fields.some(f=>f.field==='salary'))target.basisMode='salary';next.dataOrigin='manual';next.importMeta={kind:'user-file',fields:fields.map(f=>f.field),confirmed:true};return next;
}
